Function.prototype.myCall = function (thisArg, ...args) {
  const key = Symbol("fn");
  thisArg[key] = this;
  const result = thisArg[key](...args);
  delete thisArg[key];
  return result;
};

function inspect(extra) {
  return `${Object.keys(this).length} ${Reflect.ownKeys(this).length} ${extra}`;
}

const cart = { items: 2, total: 9 };

console.log(inspect.myCall(cart, "during"));
console.log(Reflect.ownKeys(cart).length);
